вида.":{},"правка шаблона зон на этот лист не действует":{"en":"edits to the zone template do not apply to this sheet","pl":"zmiana szablonu stref nie działa na ten arkusz","uk":"правка шаблону зон на цей аркуш не діє"},"правки шаблона до неё на этом листе не доходят. «Как в шаблоне» — в свойствах листа.":{},"при пределе":{},"прочие":{},"пунктир — ваша":{},"раздел выключен: лист не печатается и не нумеруется":{},"разложен руками":{},"размер шрифта комплекта":{},"раскладка её не двигает.":{},"раскладка листа: содержимое не вошло в вашу границу":{},"с":{"en":"s","pl":"s","uk":"с"},"свободно":{},"свои зоны листа":{},"сдвиг или размер блока на этом листе мышью; общие настройки и правки шаблона лист больше не перекладывают":{},"сдвиг или размер таблицы на этом листе; таблицы листа не перетекают сами":{},"сдвинута раскладкой на":{},"сейчас":{},"середина линии вида":{},"скв":{},"скв.":{"en":"thru","pl":"przel.","uk":"наскр."},"сквозное":{},"см²":{},"снизу":{},"справа":{},"стоит на ваших":{},"т.верх":{"en":"e.top","pl":"kr.góra","uk":"т.верх"},"т.лев":{"en":"e.left","pl":"kr.lewa","uk":"т.лів"},"т.низ":{"en":"e.bottom","pl":"kr.dół","uk":"т.низ"},"т.пр":{"en":"e.right","pl":"kr.prawa","uk":"т.пр"},"текстура вдоль":{},"текстура поперёк":{},"толщ.":{"en":"thk.","pl":"grub.","uk":"товщ."},"торец":{},"торцевое":{},"точек":{},"тыл":{},"тяните внутрь — зона станет меньше":{},"тяните — меняются обе соседние зоны":{},"у поля листа":{},"убрана — место отошло соседней. Вернуть — отмена или «Разделить» у соседней зоны.":{},"удалена":{"en":"deleted","pl":"usunięta","uk":"видалена"},"упор":{},"через":{"en":"in","pl":"za","uk":"через"},"шаблон":{},"шаблон вида":{},"шаблон вида на нём не виден.":{},"шаблона вида чертежей нет. Режим остаётся включённым: выберите слева лист согласования, монтажный, лист единицы, детали или сечений.":{},"шт.":{"en":"pcs","pl":"szt.","uk":"шт."},"эта картинка —":{},"— выберите зону —":{},"— выберите —":{"en":"— choose —","pl":"— wybierz —","uk":"— оберіть —"},"— добавить —":{"en":"— add —","pl":"— dodaj —","uk":"— додати —"},"✕ ряд":{"en":"✕ row","pl":"✕ wiersz","uk":"✕ ряд"},"✥ Двигать детали":{"en":"✥ Move parts","pl":"✥ Przesuwaj elementy","uk":"✥ Рухати деталі"},"✥ Двигать детали — вкл.":{"en":"✥ Move parts — on","pl":"✥ Przesuwaj elementy — wł.","uk":"✥ Рухати деталі — вкл."},"＋ Вид":{"en":"＋ View","pl":"＋ Widok","uk":"＋ Вид"},"＋ Зона":{"en":"＋ Zone","pl":"＋ Strefa","uk":"＋ Зона"},"＋ Линия":{},"＋ Новый лист после этого":{"en":"＋ New sheet after this one","pl":"＋ Nowy arkusz po tym","uk":"＋ Новий аркуш після цього"},"＋ ряд":{"en":"＋ row","pl":"＋ wiersz","uk":"＋ ряд"},"＋ ячейка":{"en":"＋ cell","pl":"＋ komórka","uk":"＋ комірка"}});

styles:
/* полноэкранный редактор чертежей */
.drawingsHistory {
  width: min(520px, 90vw);
  max-height: 80vh;
  max-height: 80dvh; /* телефон: без строки адреса браузера */
  overflow: auto;
  color: #e9f1f4;
  background: #1b252c;
  border: 1px solid #6fe3d3;
  border-radius: 8px;
}
.drawingsHistory::backdrop {
  background: #0008;
}
#drawingsHistoryList button { display: block; width: 100%; margin: 4px 0; text-align: left; }
.drawingsApp {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  grid-template-columns: 200px 1fr 290px;
  grid-template-rows: auto 1fr;
  background: #1b252c;
  color: var(--text, #e9f1f4);
  font: 13px/1.35 var(--ui-font, system-ui);
}
.drawingsApp[hidden] {
  display: none;
}
.drawingsBar {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  background: #121a20;
  border-bottom: 1px solid #2c3a44;
}
.drawingsTitle {
  margin-right: 8px;
  font-size: 15px;
}
.drawingsSpacer {
  flex: 1;
}
.drawingsPrimary {
  background: #315e5d;
  border-color: var(--accent, #6fe3d3);
}
.drawingsSheets {
  overflow: auto;
  padding: 8px;
  border-right: 1px solid #2c3a44;
}
.drawingsSheetItem {
  display: block;
  width: 100%;
  margin-bottom: 8px;
  padding: 5px;
  border: 1px solid #34454f;
  border-radius: 6px;
  background: #22303a;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.drawingsSheetItem.on {
  border-color: var(--accent, #6fe3d3);
  background: #284048;
}
.drawingsSheetItem small {
  display: block;
  color: #9fb0b8;
}
.drawingsStage {
  position: relative;
  overflow: auto;
  background: #59656c;
}
.drawingsPaper {
  margin: 24px auto;
  width: max-content;
  box-shadow: 0 6px 24px #0008;
}
.drawingsPaper svg {
  display: block;
  background: #fff;
}
.drawingsZoom {
  position: sticky;
  left: 100%;
  bottom: 10px;
  float: right;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
  margin: 0 10px 10px 0;
}
/* масштаб листа — однотипные кнопки в ряд; «Тонкие линии» (DRAW-034) — своей строкой над ним */
.drawingsZoomRow {
  display: flex;
  gap: 4px;
}
/* телефон: над листом — только масштаб (лист и так мал); «Тонкие линии» — во вкладке «Настройки» */
@media (max-width: 700px) {
  .drawingsZoom > .drawingsThinLines {
    display: none;
  }
}
.drawingsProps {
  overflow: auto;
  padding: 10px;
  border-left: 1px solid #2c3a44;
}
.drawingsProps h4 {
  margin: 12px 0 6px;
  font-size: 13px;
  color: #b7c8d0;
}
.drawingsProps h4:first-child {
  margin-top: 0;
}
.drawingsField {
  display: grid;
  grid-template-columns: 96px 1fr;
  align-items: center;
  gap: 6px;
  margin-bottom: 5px;
}
.drawingsField span {
  color: #b7c8d0;
}
/* подпись строкой над капсулой (choiceField o.wide, «Компоновка» шаблона — П-Ч29) */
.drawingsField.drawingsFieldWide {
  /* minmax(0, …): столбец не шире панели — иначе капсула шириной max-content раздвигает его
     и панель прокручивается вбок (DRAW-048, «Одинаковые детали» из трёх вариантов) */
  grid-template-columns: minmax(0, 1fr);
  gap: 3px;
}
.drawingsField input,
.drawingsField select,
.drawingsField textarea {
  width: 100%;
  box-sizing: border-box;
}
.drawingsField textarea {
  min-height: 60px;
}
/* поле с шагом (stepField): масштаб вида 1:N (DRAW-026) [−][поле][+][Авто], названия ячеек
   рамки (П-Ч31) [−][поле][+][Как раньше] — одно поле, по содержимому */
.drawingsScale {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  justify-self: start;
}
.drawingsField .drawingsScale input {
  width: 64px;
  min-height: 28px;
  text-align: center;
}
.drawingsScale .drawingsIconOnly {
  min-width: 28px;
  padding: 3px;
  justify-content: center;
}
@media (pointer: coarse) {
  .drawingsField .drawingsScale input,
  .drawingsScale .drawingsIconOnly {
    min-height: 44px;
    min-width: 44px;
  }
}
.drawingsProps .drawingsButtons {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
/* кнопки выбранного размера и «Вернуть размеры вырезов» (DRAW-087) — столбцом, шириной по подписи */
.drawingsProps .drawingsButtonCol {
  flex-direction: column;
  align-items: flex-start;
}
.drawingsDanger {
  border-color: #b06a5e;
  color: #ffc4ba;
}
/* размеры по точкам вида (DRAW-016): свёрнутый список, строка — вид и значение */
.drawingsDimList {
  margin: 6px 0;
}
.drawingsDimList > summary {
  cursor: pointer;
  color: #b7c8d0;
  font-size: 12px;
  font-weight: 600;
}
.drawingsProps .drawingsDimList > button.drawingsDimItem {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  min-height: 22px;
  margin: 2px 0 0;
  padding: 1px 8px;
  text-align: left;
}
.drawingsDimItem > b {
  font-weight: 600;
}
.drawingsDimItem.on {
  border-color: var(--accent, #6fe3d3);
  color: var(--accent, #6fe3d3);
}
.drawingsDimItem.drawingsDimLost {
  color: #e57373;
}
/* фильтр строк «Материалов»: глаз и название рядом, длинное переносится (DRAW-019) */
.drawingsMatRow {
  display: flex;
  align-items: flex-start;
  gap: 4px;
  margin-top: 2px;
  font-size: 12px;
  line-height: 1.3;
}
.drawingsMatRow > span {
  min-width: 0;
  padding-top: 3px;
  overflow-wrap: anywhere;
}
@media (pointer: coarse) {
  .drawingsProps .drawingsDimList > button.drawingsDimItem {
    min-height: 44px;
  }
  .drawingsMatRow {
    min-height: 44px;
    align-items: center;
  }
}
/* блоки на листе: рамка выбора и ручка размера рисуются в SVG */
.drawingsBlock {
  cursor: move;
}
.drawingsHandle {
  cursor: nwse-resize;
}
/* зацепы по сторонам: курсор — по направлению тяги (у рамки проекций — DRAW-039) */
.drawingsHandle[data-edge='n'],
.drawingsHandle[data-edge='s'],
.drawingsGroupHandle[data-edge='n'],
.drawingsGroupHandle[data-edge='s'] {
  cursor: ns-resize;
}
.drawingsHandle[data-edge='w'],
.drawingsHandle[data-edge='e'],
.drawingsGroupHandle[data-edge='w'],
.drawingsGroupHandle[data-edge='e'] {
  cursor: ew-resize;
}
.drawingsHandle[data-edge='ne'],
.drawingsHandle[data-edge='sw'],
.drawingsGroupHandle[data-edge='ne'],
.drawingsGroupHandle[data-edge='sw'] {
  cursor: nesw-resize;
}
.drawingsGroupHandle[data-edge='nw'],
.drawingsGroupHandle[data-edge='se'] {
  cursor: nwse-resize;
}
.drawingsGroupTab {
  cursor: move;
}
/* отверстия листа детали (DRAW-030): щелчок по отверстию, номеру или строке таблицы — выбор;
   выбранное — цветом выбора чертежа детали сборщика (#c14422), только на экране */
#drawingsPaper .drawingsHole,
#drawingsPaper .drawingsHoleNum,
#drawingsPaper .drawingsHoleRow {
  cursor: pointer;
}
#drawingsPaper .drawingsHole[data-on] > :not(.drawingsHoleHit) {
  stroke: #c14422;
  stroke-width: 0.45px;
}
#drawingsPaper .drawingsHole[data-on] > .drawingsHoleHit {
  fill: rgba(193, 68, 34, 0.22);
}
#drawingsPaper .drawingsHole[data-on] > line.drawingsHoleHit {
  stroke: rgba(193, 68, 34, 0.22);
}
#drawingsPaper .drawingsHoleNum[data-on] text {
  fill: #c14422;
}
#drawingsPaper .drawingsHoleNum[data-on] line {
  stroke: #c14422;
  stroke-width: 0.3px;
}
#drawingsPaper .drawingsHoleRow[data-on] > .drawingsHoleRowBg {
  fill: rgba(193, 68, 34, 0.2);
}
#drawingsPaper .drawingsHoleRow[data-on] text {
  font-weight: 700;
}
/* печать: только листы, каждый своим форматом (имя страницы — формат+ориентация) */
.drawingsPrintRoot {
  display: none;
}
@media print {
  body > *:not(.drawingsPrintRoot) {
    display: none !important;
  }
  .drawingsPrintRoot {
    display: block;
  }
  .drawingsPrintRoot svg {
    display: block;
    break-after: page;
  }
}
@media (max-width: 900px) {
  .drawingsApp {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto 1fr auto;
  }
  .drawingsSheets {
    display: flex;
    gap: 6px;
    border-right: 0;
    border-bottom: 1px solid #2c3a44;
  }
  .drawingsSheetItem {
    width: auto;
    margin: 0;
  }
  .drawingsProps {
    max-height: 38vh;
    border-left: 0;
    border-top: 1px solid #2c3a44;
  }
}
.drawingsHint {
  display: block;
  margin: 2px 0 8px;
  color: #9fb0b8;
}
/* шаблон рамки: ряд — ячейки (поле, доля ширины, ✕) */
.drawingsStampRow {
  margin: 6px 0;
  padding: 6px;
  border: 1px solid #34454f;
  border-radius: 6px;
}
.drawingsStampRow > small {
  display: block;
  margin-bottom: 4px;
  color: #9fb0b8;
}
.drawingsStampCell {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-bottom: 4px;
}
.drawingsStampCell select {
  flex: 1;
  min-width: 110px;
}
.drawingsStampCell input {
  flex: 1;
  min-width: 70px;
}
.drawingsStampCell input.drawingsStampW {
  flex: none;
  width: 52px;
  min-width: 0;
}
/* список листов: «Параметры комплекта» первым, листы окрашены по виду */
.drawingsSetupItem {
  display: block;
  width: 100%;
  margin-bottom: 10px;
  padding: 7px 5px;
  border: 1px dashed #5d7380;
  border-radius: 6px;
  background: #1f2a31;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.drawingsSetupItem.on {
  border-style: solid;
  border-color: var(--accent, #6fe3d3);
  background: #284048;
}
/* цвет листа — цвет раздела, к которому лист относится (DRAW-042, этап 2: раздел → цвет);
   лист в «Свободных листах» — без класса раздела, полоса цвета рамки */
.drawingsSheetItem {
  border-left-width: 4px;
}
.drawingsSec-title {
  border-left-color: #e0b84f;
}
.drawingsSec-approval {
  border-left-color: #e06fa8;
}
.drawingsSec-mounting {
  border-left-color: #f08a4b;
}
.drawingsSec-assembly {
  border-left-color: #4fa3e0;
}
.drawingsSec-parts {
  border-left-color: #c58ae0;
}
/* лист выключенного раздела: в комплекте, открывается, но не печатается — полоса
   пунктиром, в строке формата «не печатается» */
.drawingsSheetItem.drawingsNoPrint {
  border-left-style: dashed;
}
.drawingsSheetItem.drawingsDropAt {
  box-shadow: 0 -3px 0 var(--accent, #6fe3d3);
}
/* перетаскивание листа на раздел (DRAW-014): заголовок — цель; нельзя — красным */
.drawingsSheetSectionHead.drawingsDropAt {
  border-radius: 4px;
  outline: 2px solid var(--accent, #6fe3d3);
  outline-offset: 1px;
}
.drawingsSheetItem.drawingsDropNo,
.drawingsSheetSectionHead.drawingsDropNo {
  border-radius: 4px;
  outline: 2px solid #e57373;
  outline-offset: 1px;
}
/* страница «Параметры комплекта» — вместо листа */
.drawingsOnSetup .drawingsZoom {
  display: none;
}
.drawingsOnSetup .drawingsPaper {
  width: auto;
  margin: 0;
  box-shadow: none;
}
.drawingsSetup {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 14px;
  padding: 16px;
  color: var(--text, #e9f1f4);
}
.drawingsSetup section {
  /* переход к разделу (openTemplate) — название не под вкладками, прилипшими сверху */
  scroll-margin-top: 72px;
  padding: 10px 12px;
  border: 1px solid #34454f;
  border-radius: 8px;
  background: #1f2a31;
}
.drawingsSetup h4 {
  margin: 0 0 8px;
  font-size: 13px;
  color: #b7c8d0;
}
.drawingsSetup .drawingsField {
  grid-template-columns: 120px 1fr;
}
.drawingsSetup .drawingsButtons {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.drawingsChecks {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 2px 8px;
  margin: 4px 0 8px;
}
.drawingsChecks .drawingsField {
  grid-column: 1 / -1;
}
/* шаблоны: подпись группы кнопок, подсветка раздела при переходе */
.drawingsGroup {
  margin-left: 10px;
  color: #9fb0b8;
}
.drawingsSetup section.drawingsFlash {
  border-color: var(--accent, #6fe3d3);
  box-shadow: 0 0 0 2px var(--accent, #6fe3d3);
}
.drawingsColRow {
  align-items: center;
}
.drawingsColRow input[type='checkbox'] {
  flex: none;
  min-width: 0;
}
.drawingsProject {
  cursor: crosshair;
}
/* выноски вида в свойствах */
.drawingsNoteRow > small {
  cursor: pointer;
  color: var(--text, #e9f1f4);
}
.drawingsNoteRow.on {
  border-color: var(--accent, #6fe3d3);
}
.drawingsNoteRow textarea {
  width: 100%;
  box-sizing: border-box;
  min-height: 48px;
  margin-bottom: 6px;
}
/* действия элемента вида (заметка, выносной вид, сечение) — по одному в строке (DRAW-036) */
.drawingsNoteRow > button {
  display: block;
  margin-top: 4px;
}
.drawingsNoteLabel {
  cursor: grab;
}
.drawingsSearch {
  width: 100%;
  box-sizing: border-box;
  margin-bottom: 8px;
}
.drawingsBack {
  display: block;
  width: 100%;
  margin-bottom: 8px;
  text-align: left;
}
/* окно исключений из спецификаций (DRAW-022): шапка (название, пояснение, «Готово»,
   вкладки, поиск) закреплена, список вкладки прокручивается под ней */
.drawingsDialog {
  width: min(760px, 92vw);
  max-height: 86vh;
  /* верх окна на месте при смене вкладки и поиске (высота списка меняется) */
  margin: 7vh auto auto;
  overflow: auto;
  padding: 0 16px 16px;
  border: 1px solid #34454f;
  border-radius: 10px;
  background: #1b252c;
  color: var(--text, #e9f1f4);
  font: 13px/1.35 var(--ui-font, system-ui);
}
.drawingsDialog::backdrop {
  background: #0008;
}
.drawingsDialog h3 {
  margin: 0 0 6px;
}
.drawingsDialogHead {
  position: sticky;
  top: 0;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 8px 12px;
  padding: 14px 0 8px;
  background: #1b252c;
  border-bottom: 1px solid #34454f;
}
.drawingsDialogHead > :is(.drawingsExcludeTabs, .drawingsExcludeFind) {
  grid-column: 1 / -1;
}
.drawingsDialogHead > .drawingsExcludeFind {
  margin: 0;
  padding: 5px 8px;
  border: 1px solid #4a5b66;
  border-radius: 6px;
  background: #121a20;
  color: var(--text, #e9f1f4);
  font: inherit;
}
.drawingsDialogHead > .drawingsExcludeFind::placeholder {
  color: #7f909a;
}
/* вкладки «Материалы / Фурнитура» — варианты одной настройки капсулой (Д-78), как вкладки
   «Параметров комплекта»: два варианта — значок рядом с подписью. Тот же вид — у
   .drawingsChoice (варианты настройки в строке поля, choiceField: «Листы деталей») */
.drawingsExcludeTabs,
.drawingsChoice {
  display: flex;
  flex-wrap: wrap;
  gap: 2px;
  justify-self: start;
  width: max-content;
  max-width: 100%;
  padding: 2px;
  border-radius: 8px;
  background: #121a20;
}
.drawingsChoice button[aria-pressed='true'] {
  background: #315e5d;
  color: #fff;
  box-shadow: 0 1px 3px #0006;
}
.drawingsExcludeTabs button,
.drawingsChoice button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 12px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #b7c8d0;
  font: 12px/1.3 var(--ui-font, system-ui);
  cursor: pointer;
}
.drawingsExcludeTabs button > .uiIcon,
.drawingsChoice button > .uiIcon {
  width: 16px;
  height: 16px;
  flex: none;
}
/* порядок листов «Каждый вид на отдельном листе» (П-Ч30): строка — [значок][номер и
   название][выше][ниже]; по содержимому, не шире панели */
.drawingsApartOrder {
  display: grid;
  gap: 2px;
  margin-bottom: 5px;
}
.drawingsApartHead {
  color: #b7c8d0;
}
.drawingsApartRow {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 2px;
}
.drawingsApartPick {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 3px 6px;
  text-align: left;
}
.drawingsApartPick > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.drawingsApartPick > .uiIcon,
.drawingsApartRow .drawingsIconOnly > .uiIcon {
  width: 16px;
  height: 16px;
  flex: none;
}
.drawingsApartPick[aria-pressed='true'] {
  background: #315e5d;
  color: #fff;
}
.drawingsApartRow .drawingsIconOnly {
  min-width: 28px;
  padding: 3px;
  justify-content: center;
}
@media (pointer: coarse) {
  .drawingsApartPick,
  .drawingsApartRow .drawingsIconOnly {
    min-height: 44px;
    min-width: 44px;
  }
}
/* три варианта и больше (DRAW-028, «Лицевая пласть» листа детали) — значок 16 px над подписью 11 px */
.drawingsChoice[data-many] button {
  flex-direction: column;
  gap: 1px;
  padding: 3px 8px;
  font-size: 11px;
  line-height: 1.2;
}
/* капсула над строкой (o.wide) не входит в панель — варианты в один ряд, подписи переносятся
   по словам под значком, а не уходят вбок или на вторую строку (DRAW-048) */
.drawingsFieldWide > .drawingsChoice[data-many] {
  flex-wrap: nowrap;
}
.drawingsFieldWide > .drawingsChoice[data-many] button {
  flex: 0 1 auto;
  min-width: 0;
  text-align: center;
}
.drawingsExcludeTabs button[aria-selected='true'] {
  background: #315e5d;
  color: #fff;
  box-shadow: 0 1px 3px #0006;
}
.drawingsExcludeEmpty {
  display: block;
  margin-top: 8px;
}
.drawingsExcludeEmpty[hidden] {
  display: none;
}
/* строка: картинка, артикул, название, «Спец.», «Вид» — столбцы общие для всего списка
   (subgrid), артикул не шире 16 знаков и переносится */
.drawingsExcludeList {
  display: grid;
  grid-template-columns: 28px minmax(0, max-content) minmax(0, 1fr) auto auto;
  column-gap: 8px;
  margin-top: 4px;
}
.drawingsExcludeList[hidden],
.drawingsExcludeRow[hidden] {
  display: none;
}
.drawingsExcludeRow {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: subgrid;
  align-items: center;
  padding: 3px 0;
  border-bottom: 1px solid #26343d;
}
.drawingsExcludeImg {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  overflow: hidden;
  border: 1px solid #4a5b66;
  border-radius: 4px;
  background: #fff;
}
.drawingsExcludeImg > img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.drawingsExcludeImg.drawingsExcludeNoImg {
  background: #22303a;
  color: #7f909a;
}
.drawingsExcludeImg > .uiIcon {
  width: 16px;
  height: 16px;
}
.drawingsExcludeArt {
  max-width: 16ch;
  color: #b7c8d0;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.drawingsExcludeNone {
  color: #7f909a;
}
.drawingsExcludeName {
  min-width: 0;
  overflow-wrap: anywhere;
}
.drawingsToggle {
  min-width: 46px;
  padding: 2px 6px;
  border: 1px solid #4a5b66;
  border-radius: 5px;
  background: #22303a;
  color: #7f909a;
  font: inherit;
  text-decoration: line-through;
  cursor: pointer;
}
.drawingsToggle.on {
  border-color: var(--accent, #6fe3d3);
  background: #284048;
  color: var(--text, #e9f1f4);
  text-decoration: none;
}
/* телефон: артикул над названием, картинка и кнопки — на обе строки */
@media (max-width: 760px) {
  .drawingsExcludeList {
    grid-template-columns: 28px minmax(0, 1fr) auto auto;
    column-gap: 6px;
  }
  .drawingsExcludeRow > .drawingsExcludeImg {
    grid-row: 1 / span 2;
    grid-column: 1;
  }
  .drawingsExcludeArt {
    grid-row: 1;
    grid-column: 2;
    max-width: none;
    font-size: 12px;
  }
  .drawingsExcludeName {
    grid-row: 2;
    grid-column: 2;
  }
  /* без артикула — название на обе строки, без прочерка */
  .drawingsExcludeArt.drawingsExcludeNone {
    display: none;
  }
  .drawingsExcludeNone + .drawingsExcludeName {
    grid-row: 1 / span 2;
  }
  .drawingsExcludeRow > .drawingsToggle {
    grid-row: 1 / span 2;
    grid-column: 3;
  }
  .drawingsExcludeRow > .drawingsToggle:last-child {
    grid-column: 4;
  }
}
@media (pointer: coarse) {
  .drawingsExcludeTabs button,
  .drawingsChoice button,
  .drawingsExcludeRow > .drawingsToggle {
    min-height: 44px;
  }
}
/* структура модели в свойствах листа общего вида */
/* выбранный размер (Delete удаляет) */
.drawingsDimSel line:not(.drawingsAutoDimHit):not(.drawingsMeasureHit),
.drawingsDimSel path {
  stroke: #1e88e5;
  fill: #1e88e5;
}
.drawingsDimSel text {
  fill: #1e88e5;
}
/* размер между деталями, чьих деталей нет на виде: стоит по последним точкам (только в
   редакторе, на печать — как обычный) */
#drawingsPaper .drawingsDimLost line:not(.drawingsMeasureHit),
#drawingsPaper .drawingsDimLost path {
  stroke: #ef6c00;
  fill: #ef6c00;
  stroke-dasharray: 1 0.6;
}
#drawingsPaper .drawingsDimLost text {
  fill: #ef6c00;
}
.drawingsDimTextInput {
  width: 70px;
}
.drawingsTree {
  max-height: 46vh;
  overflow: auto;
  padding: 4px 0;
  border: 1px solid #34454f;
  border-radius: 6px;
}
.drawingsTree details {
  margin-left: 10px;
}
.drawingsTree > details {
  margin-left: 2px;
}
.drawingsTree summary {
  cursor: pointer;
}
.drawingsTree label {
  display: inline-flex;
  gap: 4px;
  align-items: center;
}
/* «СЕ» у узла структуры: свой узел — сборочной единицей, рядом обозначение */
.drawingsUnitToggle {
  display: inline-flex;
  gap: 4px;
  align-items: center;
  margin-left: 6px;
}
.drawingsUnitToggle button {
  padding: 0 6px;
  font-size: 11px;
  line-height: 18px;
}
.drawingsUnitToggle button.drawingsOn {
  background: #2e7d6b;
  color: #fff;
}
.drawingsUnitCode {
  width: 70px;
  font-size: 11px;
}
/* длинное название узла переносится рядом со стрелкой, а не под неё */
.drawingsTree summary label {
  display: inline;
}
.drawingsTree .drawingsTreeAll {
  margin-left: 4px;
  padding: 0 4px;
  font-size: 11px;
  line-height: 16px;
}
.drawingsTree .drawingsTreeLeaf {
  display: flex;
  margin-left: 24px;
}
.drawingsMoveRow {
  display: flex;
  gap: 6px;
  align-items: center;
}
/* ключ к чертежам — строка в «☰ → Ещё» */
.drawingsKeyTools {
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}
.drawingsKeyTools input {
  width: 150px;
  min-width: 0;
}
.drawingsKeyTools [hidden],
#drawingsOpen[hidden] {
  display: none !important;
}

/* полки выносок позиций и размерные линии размеров по точкам тянутся мышью */
.drawingsCalloutLabel,
.drawingsMeasureHit {
  cursor: move;
}
/* «На лист…» (DRAW-008): меню листов — в общем слое (portalToolMenu), вкладка листа,
   на которую тянут блок, — подсвечена целиком */
.drawingsProps .drawingsMoveMenu > summary {
  display: inline-block;
  padding: 7px 12px;
  font: inherit;
  color: inherit;
  border: 1px solid #415563;
  border-radius: 7px;
  background: #21313e;
  cursor: pointer;
  list-style: none;
}
.drawingsProps .drawingsMoveMenu[open] > summary {
  background: #304654;
  border-color: var(--accent, #6fe3d3);
}
.drawingsMoveMenu > summary::-webkit-details-marker {
  display: none;
}
.drawingsMoveList button {
  display: block;
  width: 100%;
  margin: 3px 0;
  text-align: left;
}
.drawingsMoveList button.on {
  border-color: var(--accent, #6fe3d3);
  opacity: 0.6;
}
.drawingsSheetItem.drawingsDropBlock {
  box-shadow: none;
  outline: 2px solid var(--accent, #6fe3d3);
  outline-offset: -2px;
  background: #2a4a50;
}
/* «Параметры комплекта» — вкладки сверху (замечание 31.10.2026): варианты одной
   настройки — капсулой, как режимы отображения вверху (Д-78) */
.drawingsSetupTabs {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 2px;
  width: max-content;
  max-width: calc(100% - 32px);
  margin: 12px 16px 0;
  padding: 2px;
  border-radius: 8px;
  background: #121a20;
}
.drawingsSetupTabs button {
  padding: 4px 12px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #b7c8d0;
  font: 12px/1.3 var(--ui-font, system-ui);
  cursor: pointer;
}
.drawingsSetupTabs button[aria-selected='true'] {
  background: #315e5d;
  color: #fff;
  box-shadow: 0 1px 3px #0006;
}
.drawingsSetup section[hidden] {
  display: none;
}
/* «Изделие»: поле и глаз видимости в строку; логотип — превью и кнопки */
.drawingsInfoRow {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 5px;
}
.drawingsInfoRow > .drawingsField {
  flex: 1;
  min-width: 0;
  margin: 0;
}
.drawingsApp label.uiEye.drawingsInfoEye,
.drawingsApp label.uiEye.drawingsSectionEye {
  flex: none;
  min-height: 0;
  padding: 3px;
  border: 0;
  background: transparent;
}
.drawingsApp label.uiEye > .uiLabel:empty {
  display: none;
}
.drawingsLogo {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.drawingsLogo img {
  max-width: 120px;
  max-height: 32px;
  padding: 2px;
  border-radius: 4px;
  background: #fff;
}
/* кнопка: значок + подпись; кнопка только со значком */
.drawingsIconBtn,
.drawingsIconOnly {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.drawingsIconOnly {
  flex: none;
  padding: 3px;
}
.drawingsIconBtn > .uiIcon,
.drawingsIconOnly > .uiIcon {
  width: 16px;
  height: 16px;
}
/* значок на странице параметров — не лист: без белого фона .drawingsPaper svg */
.drawingsPaper svg.uiIcon {
  display: inline-block;
  background: none;
}
/* рамка: раскладка рядов и полей; в режиме правки — тянуть и менять местами */
.drawingsStampLayout {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  margin: 4px 0 10px;
}
.drawingsStampLayoutRow {
  display: flex;
  align-self: stretch;
  min-width: 0;
}
.drawingsStampLayoutCell {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
  padding: 4px 6px;
  overflow: hidden;
  border: 1px solid #5d7380;
  margin-left: -1px;
  background: #22303a;
  color: #b7c8d0;
  font-size: 11px;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.drawingsStampLayout.on .drawingsStampLayoutCell {
  overflow: visible;
  cursor: grab;
}
.drawingsStampLayoutCell.drawingsDropAt {
  background: #284048;
  outline: 2px solid var(--accent, #6fe3d3);
}
.drawingsStampGrip {
  position: absolute;
  top: 0;
  right: -4px;
  bottom: 0;
  z-index: 1;
  width: 7px;
  cursor: col-resize;
}
.drawingsStampGrip:hover {
  background: var(--accent, #6fe3d3);
}
/* список листов: разделы — блоки с названием, числом листов, настройками и глазом */
.drawingsSheetSection {
  margin-bottom: 8px;
  padding: 4px;
  border: 1px solid #2c3a44;
  border-radius: 6px;
}
.drawingsSheetSection[hidden] {
  display: none;
}
.drawingsSheetSectionHead {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 4px;
}
.drawingsSheetSectionName {
  min-width: 0;
  color: #b7c8d0;
  font-size: 12px;
  font-weight: 600;
}
.drawingsSheetSectionHead > small {
  flex: 1;
  color: #9fb0b8;
}
.drawingsSheetSection .drawingsSheetItem:last-child {
  margin-bottom: 0;
}
.drawingsSheetSection > .drawingsHint {
  margin: 0;
}
.drawingsSheetSectionSettings {
  margin-bottom: 6px;
}
.drawingsSheetSectionSettings .drawingsField {
  grid-template-columns: 52px 1fr;
}
/* зона «Виды» шаблона: настройки выбранного вида */
.drawingsSlotBox {
  margin: 8px 0;
  padding: 6px 8px;
  border: 1px solid #34454f;
  border-radius: 6px;
}
@media (max-width: 900px) {
  .drawingsSheetSection {
    display: flex;
    flex: none;
    align-items: stretch;
    gap: 6px;
    margin: 0;
  }
  .drawingsSheetSectionHead {
    flex-direction: column;
    justify-content: center;
    margin: 0;
  }
  .drawingsSheetSection > .drawingsHint {
    align-self: center;
    max-width: 140px;
  }
}
/* панель вкладками (П-Ч6): верхняя строка и строка инструментов открытой вкладки;
   кнопки компактные, как в верхней строке просмотрщика (Д-78) */
.drawingsApp .drawingsBar {
  flex-direction: column;
  flex-wrap: nowrap;
  align-items: stretch;
  gap: 4px;
}
.drawingsBarTop,
.drawingsRibbon {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
}
.drawingsRibbon[hidden] {
  display: none;
}
.drawingsTool {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 28px;
  padding: 3px 9px;
  font-size: 12px;
}
.drawingsTool > .uiIcon {
  width: 16px;
  height: 16px;
}
.drawingsToolIcon {
  padding: 3px 6px;
}
.drawingsRedo > .uiIcon {
  transform: scaleX(-1);
}
.drawingsRibbonTabs {
  display: flex;
  gap: 2px;
  margin-left: 8px;
  padding: 2px;
  border-radius: 8px;
  background: #0c1216;
}
.drawingsRibbonTabs button {
  padding: 4px 12px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #b7c8d0;
  font: 12px/1.3 var(--ui-font, system-ui);
  cursor: pointer;
}
.drawingsRibbonTabs button[aria-selected='true'] {
  background: #315e5d;
  color: #fff;
  box-shadow: 0 1px 3px #0006;
}
/* слои вида и флажки раздела — столбцом, глаз видимости компактный */
.drawingsLayers {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  margin: 6px 0;
}
.drawingsLayers > .drawingsHint {
  margin: 0 0 2px;
}
.drawingsApp .drawingsLayers label.uiEye {
  min-height: 26px;
  padding: 0 8px;
  gap: 6px;
  font-size: 12px;
}
/* телефон: цель касания строки-глаза — 44 px (ui-rules, п. 5а; DRAW-070) */
@media (pointer: coarse) {
  .drawingsApp .drawingsLayers label.uiEye {
    min-height: 44px;
  }
}
.drawingsSectionCheck {
  display: block;
  margin: 2px 0;
  color: #b7c8d0;
}
.drawingsSheetSectionSettings .drawingsChecks {
  grid-template-columns: 1fr;
}
.drawingsNote {
  color: var(--accent, #6fe3d3);
}
@media (pointer: coarse) {
  .drawingsTool,
  .drawingsRibbonTabs button {
    min-height: 44px;
  }
}
/* «Обновить модель» вверху — заметно, когда модель изменилась (П-Ч13) */
.drawingsTool.drawingsAttention {
  border-color: #e0b84f;
  background: #4a3f1c;
  color: #ffe6a3;
}
/* кнопки в свойствах — компактные, как в панели сверху (Д-78) */
.drawingsProps button,
.drawingsSetup button {
  min-height: 28px;
  padding: 3px 9px;
  font-size: 12px;
}
.drawingsToolRow {
  gap: 4px;
}
@media (pointer: coarse) {
  .drawingsProps button,
  .drawingsSetup button {
    min-height: 44px;
  }
}
.drawingsTool[hidden] {
  display: none;
}
/* строка узла структуры — сеткой (владелец, 01.11.2026): стрелка | название
   (переносится) | «развернуть ветку» | «СЕ»; обозначение единицы — строкой ниже */
.drawingsTree summary {
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr) 24px 34px;
  align-items: start;
  column-gap: 4px;
  padding: 1px 4px 1px 0;
  list-style: none;
}
.drawingsTree summary::-webkit-details-marker {
  display: none;
}
.drawingsTree summary::before {
  content: '';
  grid-column: 1;
  width: 5px;
  height: 5px;
  margin: 6px 0 0 1px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(-45deg);
}
.drawingsTree details[open] > summary::before {
  transform: rotate(45deg);
}
.drawingsTree summary > label {
  grid-column: 2;
  display: flex;
  align-items: flex-start;
  min-width: 0;
  overflow-wrap: anywhere;
}
.drawingsTree summary > .drawingsTreeAll {
  grid-column: 3;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  min-height: 22px;
  margin: 0;
  padding: 0;
}
.drawingsTree summary > .drawingsTreeAll > .uiIcon {
  width: 16px;
  height: 16px;
}
.drawingsTree summary > .drawingsUnitToggle {
  display: contents;
}
.drawingsTree summary > .drawingsUnitToggle > button {
  grid-column: 4;
  min-height: 22px;
  margin: 0;
}
.drawingsTree summary > .drawingsUnitToggle > .drawingsUnitCode {
  grid-column: 2 / -1;
  width: auto;
  margin: 2px 0;
}
.drawingsTree .drawingsTreeLeaf {
  margin-left: 24px;
  align-items: flex-start;
  overflow-wrap: anywhere;
}
/* редактор разделов: листы раздела и настройки видов — раскрывающимися блоками */
.drawingsSectionSheet,
.drawingsSectionSlot {
  margin: 4px 0;
  padding: 2px 6px;
  border: 1px solid #34454f;
  border-radius: 6px;
}
.drawingsSectionSheet > summary,
.drawingsSectionSlot > summary {
  padding: 3px 0;
  color: #b7c8d0;
  cursor: pointer;
}
.drawingsSectionSlot > .drawingsSlotBox {
  margin: 4px 0;
  padding: 0;
  border: 0;
}
/* карточки параметров — по своему содержимому, без растяжения по соседу */
.drawingsSetup {
  align-items: start;
}
/* П-Ч27: разделы комплекта — друг под другом, все настройки видны сразу; высоту ряда
   больше не задаёт длинный раздел соседа. Переходы на листы — в списке слева (П-Ч28) */
.drawingsSetup[data-tab='sections'] {
  grid-template-columns: minmax(0, 1fr);
}
/* ряд «Чертёж» (П-Ч23): выноски и размеры — под лентой, своей строкой с подписью;
   включённый инструмент — нажат */
.drawingsDrawRow {
  padding-top: 4px;
  border-top: 1px solid #2c3a44;
}
.drawingsRowLabel {
  margin-right: 4px;
  color: #8fa3ad;
  font-size: 11px;
}
.drawingsTool[aria-pressed='true'] {
  border-color: #4fb3a6;
  background: #315e5d;
  color: #fff;
}
.drawingsPickStatus {
  display: block;
  margin: 2px 0 4px;
  color: var(--accent, #6fe3d3);
}
/* телефон: ряды ленты — одной строкой, прокрутка вбок внутри ряда (как список листов),
   а не пол-экрана переносов (П-Ч23) */
@media (max-width: 700px) {
  .drawingsApp .drawingsBar {
    min-width: 0;
  }
  .drawingsRibbon {
    min-width: 0;
    flex-wrap: nowrap;
    overflow-x: auto;
    scrollbar-width: none;
  }
  .drawingsRibbon > * {
    flex: none;
  }
}
/* Список под курсором (П-Ч26): детали или блоки под инструментом размера — в общем
   верхнем слое у курсора, компактный (Д-78); строки — название и позиция, как в дереве */
.drawingsPickMenu {
  position: fixed;
  z-index: 240;
  max-width: 296px;
  max-height: 50vh;
  overflow: auto;
  padding: 4px;
  background: #17232d;
  border: 1px solid #415563;
  border-radius: 8px;
  box-shadow: 0 12px 35px #0006;
  scrollbar-width: thin;
}
.drawingsPickMenu > small {
  display: block;
  padding: 2px 6px 4px;
  font-size: 11px;
  color: #9fb3bf;
}
.drawingsPickMenu > button {
  display: block;
  width: 100%;
  margin: 0;
  padding: 4px 8px;
  font-size: 12px;
  text-align: left;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--text, #e8f0f2);
  background: none;
  border: 0;
  border-radius: 5px;
}
.drawingsPickMenu > button:hover,
.drawingsPickMenu > button:focus-visible {
  background: #304654;
}
.drawingsPickMenu > button:focus-visible {
  outline: 2px solid #9ee2d0;
  outline-offset: -2px;
}
@media (pointer: coarse) {
  .drawingsPickMenu > button {
    min-height: 44px;
  }
}
/* DRAW-034: окно выбора точки, когда рядом несколько — в body поверх всего, как список под
   курсором; кадр места крупно с номерами, под ним — номера кнопками (однотипные варианты
   одного выбора — в ряд) */
.drawingsSnapPick {
  position: fixed;
  z-index: 240;
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: max-content;
  padding: 4px;
  background: #17232d;
  border: 1px solid #415563;
  border-radius: 8px;
  box-shadow: 0 12px 35px #0006;
}
.drawingsSnapPick > small {
  display: block;
  max-width: 0;
  min-width: 100%;
  padding: 2px 4px 0;
  font-size: 11px;
  color: #9fb3bf;
}
.drawingsSnapView {
  display: block;
  border-radius: 5px;
  cursor: pointer;
}
.drawingsSnapNums {
  display: flex;
  flex-wrap: wrap;
  gap: 2px;
}
.drawingsSnapNums > button {
  min-width: 24px;
  height: 24px;
  margin: 0;
  padding: 0 6px;
  font-size: 12px;
  font-weight: 700;
  color: var(--text, #e8f0f2);
  background: #22323d;
  border: 0;
  border-radius: 5px;
}
.drawingsSnapNums > button:hover,
.drawingsSnapNums > button[aria-current='true'] {
  background: #304654;
  box-shadow: inset 0 0 0 1px #e53935;
}
.drawingsSnapNums > button:focus-visible {
  outline: 2px solid #9ee2d0;
  outline-offset: 2px;
}
@media (pointer: coarse) {
  .drawingsSnapNums > button {
    min-width: 44px;
    height: 44px;
  }
}
/* DRAW-080: вид привязки в окне «Точки рядом» (П-Ч88) — у номера значок и название вида («1 Конец»);
   номера переносятся по ширине кадра места и окно не расширяют */
.drawingsSnapPick > .drawingsSnapNums {
  max-width: 0;
  min-width: 100%;
}
.drawingsSnapPick .drawingsSnapNums > button {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 0 6px 0 4px;
  white-space: nowrap;
}
.drawingsSnapKind {
  flex: none;
  width: 14px;
  height: 14px;
}
/* ==== DRAW-083: подпись привязки у курсора и памятка значков привязок (П-Ч87, Д-203) ==== */
/* подпись у курсора: значок и название вида привязки; поверх сцены, щелчки проходят сквозь неё; место у курсора
   считает pick.js (snapTag) — лупу, точку и край сцены обходит */
.drawingsSnapTag {
  position: fixed;
  z-index: 25;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 220px;
  padding: 2px 8px 2px 4px;
  border: 1px solid #415563;
  border-radius: 6px;
  background: #17232d;
  color: #e9f1f4;
  font-size: 12px;
  line-height: 1.3;
  white-space: nowrap;
  pointer-events: none;
  box-shadow: 0 2px 8px #0008;
}
.drawingsSnapTag > .drawingsSnapKind {
  width: 16px;
  height: 16px;
}
/* памятка в свойствах: строка — значок слева, название рядом; столбцом (один элемент — одна строка) */
.drawingsSnapLegend {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  margin: 0 0 8px;
  color: #b7c8d0;
}
.drawingsSnapLegend > span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.drawingsSnapLegend .drawingsSnapKind {
  width: 16px;
  height: 16px;
}
/* без «Подписей» — значки, название в подсказке строки */
html.drawingsNoLabels .drawingsSnapLegend .drawingsSnapName {
  display: none;
}
@media print {
  .drawingsSnapTag {
    display: none !important;
  }
}
/* ==== /DRAW-083 ==== */
/* «Настройки шаблона» (DRAW-039, П-Ч34…П-Ч37). Лента режима: «Сохранить шаблон…», «Загрузить
   шаблон…», «Мои шаблоны…» — кнопки-меню (details) вида соседних кнопок ленты; окна — в общем
   верхнем слое (portalToolMenu), содержимое столбцом, по одному элементу в строке */
.drawingsTplMenu {
  position: relative;
  display: inline-block;
}
.drawingsTplMenu > summary {
  list-style: none;
  border: 1px solid #415563;
  border-radius: 7px;
  background: #21313e;
  color: inherit;
  cursor: pointer;
}
.drawingsTplMenu > summary.drawingsPrimary {
  background: #315e5d;
  border-color: var(--accent, #6fe3d3);
}
.drawingsTplMenu > summary::-webkit-details-marker {
  display: none;
}
.drawingsTplMenu[open] > summary {
  background: #304654;
  border-color: var(--accent, #6fe3d3);
}
.drawingsTplMenu > summary[aria-disabled='true'] {
  opacity: 0.5;
  cursor: default;
}
.drawingsTplMenu > summary:focus-visible,
.drawingsTplPop button:focus-visible,
.drawingsTplSection button:focus-visible,
.drawingsTplBox button:focus-visible,
.drawingsPanelHead button:focus-visible {
  outline: 2px solid #9ee2d0;
  outline-offset: 2px;
}
/* без оболочки (нет portalToolMenu) — обычное окно под кнопкой */
.drawingsTplMenu > .toolPopup:not(.toolPopupPortal) {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  z-index: 240;
  width: 282px;
  max-width: calc(100vw - 20px);
  max-height: 70vh;
  overflow: auto;
  background: #1b252c;
  border: 1px solid #415563;
  border-radius: 8px;
}
.drawingsTplPop {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
  padding: 8px 10px 10px;
  color: #e9f1f4;
  font: 13px/1.35 var(--ui-font, system-ui);
}
.drawingsTplPop .drawingsHint {
  margin: 0;
}
.drawingsTplPopHead {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  font-size: 13px;
}
.drawingsTplPopHead > span {
  flex: 1;
  min-width: 0;
}
.drawingsTplPopHead > .uiIcon {
  flex: none;
  width: 16px;
  height: 16px;
}
.drawingsTplPop .drawingsTool,
.drawingsTplBox .drawingsTool {
  align-self: flex-start;
  max-width: 100%;
  text-align: left;
}
.drawingsTplPop .drawingsToolLabel,
.drawingsTplBox .drawingsToolLabel {
  min-width: 0;
  overflow-wrap: anywhere;
}
.drawingsTplNameField {
  display: flex;
  flex-direction: column;
  gap: 2px;
  color: #9fb0b8;
  font-size: 12px;
}
.drawingsTplNameField > input {
  width: 100%;
  box-sizing: border-box;
}
.drawingsTplError {
  color: #ffb4a8;
}
.drawingsTplError:empty {
  display: none;
}
/* список «Загрузить»: значок выбора, название (переносится), звезда или «встроенный» */
.drawingsTplPick {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.drawingsTplPick > button {
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr) auto;
  align-items: center;
  gap: 6px;
  min-height: 28px;
  padding: 3px 8px;
  text-align: left;
  font-size: 12px;
}
.drawingsTplPick > button[aria-current='true'] {
  border-color: var(--accent, #6fe3d3);
}
.drawingsTplPick .uiIcon,
.drawingsTplMark .uiIcon {
  width: 16px;
  height: 16px;
}
.drawingsTplPickName {
  overflow-wrap: anywhere;
}
.drawingsTplPick small {
  color: #9fb0b8;
}
.drawingsLinkButton {
  display: inline;
  min-height: 0 !important;
  padding: 0 !important;
  border: 0;
  background: none;
  color: var(--accent, #6fe3d3);
  font: inherit;
  text-decoration: underline;
  cursor: pointer;
}
/* панель режима: шапка [Настройки шаблона][?][×] (элементы друг за другом), контейнеры */
.drawingsPanelHead {
  display: flex;
  align-items: center;
  gap: 4px;
  margin: 0 0 6px;
}
.drawingsPanelHead > h3 {
  flex: 0 1 auto;
  min-width: 0;
  margin: 0 4px 0 0;
  font-size: 14px;
}
.drawingsTplKind > b {
  color: #e9f1f4;
}
.drawingsTplWarn {
  color: #ffd98a;
}
.drawingsTplBox {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
  margin: 8px 0;
  padding: 6px 8px 8px;
  border: 1px solid #2f414c;
  border-radius: 8px;
}
.drawingsTplBox > h4 {
  display: flex;
  align-items: baseline;
  gap: 6px;
  margin: 0 0 2px;
}
.drawingsTplBox > h4 > .uiIcon {
  flex: none;
  align-self: center;
  width: 16px;
  height: 16px;
}
.drawingsTplBox > h4 > small {
  color: #9fb0b8;
  font-weight: 400;
}
.drawingsTplBox > .drawingsHint {
  margin: 2px 0 0;
}
.drawingsTplStatus small {
  color: #9fb0b8;
}
.drawingsTplStar[aria-pressed='true'] > .uiIcon,
.drawingsTplIcon[aria-pressed='true'] > .uiIcon {
  color: #e0b84f;
  fill: currentColor;
}
/* список листов в режиме: шаблон вида раздела (точка — изменён) и метка листа вне шаблона */
.drawingsSheetSection > .drawingsTplName {
  display: block;
  margin: 0 0 6px;
  color: #9fb0b8;
  overflow-wrap: anywhere;
}
.drawingsTplDirty {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-left: 5px;
  border-radius: 50%;
  background: #e0b84f;
  vertical-align: middle;
}
.drawingsTplTag {
  display: block;
  color: #ffd98a;
}
