:is(.drawingsProps, .drawingsSetup) .drawingsButtons > button:has(> .uiIcon),
.drawingsProps > button:not([class]):has(> .uiIcon),
.drawingsProps .drawingsMoveMenu > summary:has(> .uiIcon),
.drawingsMoveList > button:has(> .uiIcon) {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.drawingsMoveList > button:has(> .uiIcon) {
  display: flex;
}
:is(.drawingsProps, .drawingsSetup) .drawingsButtons > button > .uiIcon,
.drawingsProps > button > .uiIcon,
.drawingsProps .drawingsMoveMenu > summary > .uiIcon,
.drawingsMoveList > button > .uiIcon {
  flex: none;
  width: 16px;
  height: 16px;
}
/* «Назад: N. Лист» — стрелка значком (DRAW-072) */
.drawingsBack:has(> .uiIcon) {
  display: flex;
  align-items: center;
  gap: 6px;
}
.drawingsBack > .uiIcon {
  flex: none;
  width: 16px;
  height: 16px;
}
/* ==== DRAW-079: вкладка «Черчение» и ряды размеров — одним блоком (К3 плана DRAW-074; П-Ч85, П-Ч93, П-Ч94, П-Ч97) ==== */
/* на вкладке «Черчение» ряда «Чертёж» нет (Д-200): выноски и виды — под лентой других вкладок */
.drawingsDrawRow.drawingsOffTab {
  display: none;
}
/* блок инструментов вкладки «Черчение» (Д-201): название и кнопки одним контейнером по содержимому; блоки — друг за
   другом в ряд, переносятся, только когда следующий не входит */
.drawingsDraftRibbon {
  align-items: stretch;
  gap: 6px;
}
.drawingsToolGroup {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  padding: 2px 4px 2px 8px;
  border: 1px solid #2c3a44;
  border-radius: 8px;
}
.drawingsToolGroup:empty {
  display: none;
}
/* ряд размеров: невидимая линия звена (за неё выбирают и тянут) не красится выбором и пометкой потерянного */
#drawingsPaper .drawingsDimSel line.drawingsDimSetHit,
#drawingsPaper .drawingsDimLost line.drawingsDimSetHit {
  stroke: transparent;
}
/* ряд ставится — бледнее */
#drawingsPaper .drawingsDimSet.drawingsDraft {
  opacity: 0.75;
}
/* свойства ряда: действия столбцом, по подписи (один элемент — одна строка) */
.drawingsDimSetActs {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  margin: 4px 0 8px;
}
.drawingsDimSetActs > button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.drawingsDimSetActs > button > .uiIcon {
  flex: none;
  width: 16px;
  height: 16px;
}
html.drawingsNoLabels .drawingsDimSetActs > button > span:not(.uiIcon) {
  display: none;
}
.drawingsHint.drawingsWarn {
  color: #ffb74d;
}
@media (pointer: coarse) {
  .drawingsDimSetActs > button {
    min-height: 44px;
  }
}
/* телефон: вкладки ленты и блок «Черчения» — одной строкой с прокруткой вбок, как ряды ленты (П-Ч23): верхняя
   строка не шире экрана */
@media (max-width: 700px) {
  .drawingsRibbonTabs {
    min-width: 0;
    overflow-x: auto;
    scrollbar-width: none;
  }
  .drawingsRibbonTabs > button {
    flex: none;
  }
  .drawingsToolGroup {
    flex-wrap: nowrap;
    max-width: none;
  }
  /* без подписей ряд ленты переносится (значки видны все) — и блок */
  html.drawingsNoLabels .drawingsToolGroup {
    flex-wrap: wrap;
    max-width: 100%;
  }
}
/* ==== /DRAW-079 ==== */
